syntax:
namespace NamespaceName {
    // Declarations
}

// Definition outside the namespace
ReturnType NamespaceName::MemberName(ParameterList) {
    // function body
}

code_example:
#include <iostream>
namespace Q {
    namespace V {
        void f();
    }
    void V::f() {
        std::cout << "Function V::f() called" << std::endl;
    }
    void V::g() {
        std::cout << "Function V::g() called" << std::endl;
    }
}
int main() {
    Q::V::f(); // Calls the explicitly qualified function
    // Q::V::g(); // Error: g() is not yet declared in namespace V
    return 0;
}
